sys_script.script:
// Business Rule on sys_user — After Insert
// When a new user is created, auto-create their onboarding checklist items

var items = [
    { description: 'Collect your laptop from IT Hardware', order: 1 },
    { description: 'Set up company email', order: 2 },
    { description: 'Connect to VPN', order: 3 },
    { description: 'Read Acceptable Use Policy', order: 4 },
    { description: 'Request software access', order: 5 },
    { description: 'Complete IT security training', order: 6 },
    { description: 'Set up two-factor authentication', order: 7 },
    { description: 'Submit workplace access request', order: 8 }
];

items.forEach(function(item) {
    var gr = new GlideRecord('x_2062828_launch_0_x_onboard_checklist_item');
    gr.setValue('assigned_to', current.sys_id);
    gr.setValue('short_description', item.description);
    gr.setValue('u_order', item.order);
    gr.setValue('state', '1');
    gr.insert();
});
